1	using System.Collections.ObjectModel;
2	using System.ComponentModel;
3	using Newtonsoft.Json;
4	
5	namespace Engine.Models;
6	
7	public abstract class LivingEntity : INotifyPropertyChanged
8	{
9	    private GameItem? _currentWeapon;
10	    private GameItem? _currentConsumable;
11	
12	    public event PropertyChangedEventHandler? PropertyChanged;
13	
14	    public ObservableCollection<PlayerAttribute> Attributes {get;} =
15	        new ObservableCollection<PlayerAttribute>();
16	
17	    public string Name {get;}
18	    public int CurrentHitPoints {get; private set;}
19	    public int MaximumHitPoints {get; protected set;}
20	    public int Gold {get; private set;}
21	    public int Level {get; protected set;}
22	    public Inventory Inventory {get; private set;}
23	
24	    public GameItem? CurrentWeapon
25	    {
26	        get{return _currentWeapon;}
27	        set
28	        {
29	            if(_currentWeapon?.Action != null)
30	            {
31	                _currentWeapon.Action.OnActionPerformed -= RaiseActionPerformedEvent;
32	            }
33	            _currentWeapon = value;
34	            if(_currentWeapon?.Action != null)
35	            {
36	                _currentWeapon.Action.OnActionPerformed += RaiseActionPerformedEvent;
37	            }
38	        }
39	    }
40	
41	    public GameItem? CurrentConsumable
42	    {
43	        get{return _currentConsumable;}
44	        set
45	        {
46	            if(_currentConsumable?.Action != null)
47	            {
48	                _currentConsumable.Action.OnActionPerformed -= RaiseActionPerformedEvent;
49	            }
50	            _currentConsumable = value;
51	            if(_currentConsumable?.Action != null)
52	            {
53	                _currentConsumable.Action.OnActionPerformed += RaiseActionPerformedEvent;
54	            }
55	        }
56	    }
57	    [JsonIgnore]
58	    public bool IsAlive => CurrentHitPoints > 0;
59	    [JsonIgnore]
60	    public bool IsDead => !IsAlive;
61	    public event EventHandler<string>? OnActionPerformed;
62	    public event EventHandler? OnKilled;
63	
64	    protected LivingEntity(string name, int maximumHitPoints, int currentHitPoints,
65	                            IEnumerable<PlayerAttribute> attributes, int gold, int level = 1)
66	    {
67	        Name = name;
68	        MaximumHitPoints = maximumHitPoints;
69	        CurrentHitPoints = currentHitPoints;
70	        Gold = gold;
71	        Level = level;
72	        foreach(PlayerAttribute attribute in attributes){
73	            Attributes.Add(attribute);
74	        }
75	
76	        Inventory = new Inventory();
77	    }
78	
79	    public void UseCurrentWeaponOn(LivingEntity target)
80	    {
81	        if(CurrentWeapon == null)
82	        {
83	            return;
84	        }
85	        CurrentWeapon.PerformAction(this, target);
86	    }
87	
88	    public void UseCurrentConsumable()
89	    {
90	        GameItem? consumable = CurrentConsumable;
91	        if(consumable == null)
92	        {
93	            return;
94	        }
95	        consumable.PerformAction(this, this);
96	        RemoveItemFromInventory(consumable);
97	    }
98	
99	    public void TakeDamage(int value)
100	    {
101	        CurrentHitPoints -= value;
102	        if (IsDead)
103	        {
104	            CurrentHitPoints = 0;
105	            RaiseOnKilledEvent();
106	        }
107	    }
108	
109	    public void Heal(int value)
110	    {
111	        CurrentHitPoints += value;
112	        if(CurrentHitPoints > MaximumHitPoints)
113	        {
114	            CurrentHitPoints = MaximumHitPoints;
115	        }
116	    }
117	
118	    public void CompleteHeal()
119	    {
120	        CurrentHitPoints = MaximumHitPoints;
121	    }
122	
123	    public void ReceiveGold(int value)
124	    {
125	        Gold += value;
126	    }
127	
128	    public void SpendGold(int value)
129	    {
130	        if(value > Gold)
131	        {
132	            throw new ArgumentOutOfRangeException($"{Name} only has {Gold} gold");
133	        }
134	        Gold -= value;
135	    }
136	
137	    public void AddItemToInventory(GameItem item)
138	    {   
139	        Inventory = Inventory.AddItem(item);
140	    }
141	
142	    public void RemoveItemFromInventory(GameItem item)
143	    {
144	        ReplaceInventoryAfterRemoval(Inventory.RemoveItem(item));
145	    }
146	
147	    public void RemoveItemsFromInventory(List<ItemQuantity> itemQuantities)
148	    {
149	        ReplaceInventoryAfterRemoval(Inventory.RemoveItems(itemQuantities));
150	    }
151	
