using Engine.Models;
using System.Xml;
using Engine.Models.Shared;
using System.Reflection.Metadata;
using System.Runtime.CompilerServices;
using System.Security.Cryptography.X509Certificates;

public static class SkillFactory
{
    private static readonly string GAME_DATA_FILENAME = 
        Path.Combine(AppContext.BaseDirectory, "GameData", "Skills.xml");
    private static List<Skill> _skills = new List<Skill>();

    static SkillFactory(){
        if (File.Exists(GAME_DATA_FILENAME))
        {
            XmlDocument data = new XmlDocument();
            data.LoadXml(File.ReadAllText(GAME_DATA_FILENAME));
            LoadSkillsFromNodes(data.SelectNodes("/Skills/Skill"));
        }
    }

    private static void LoadSkillsFromNodes(XmlNodeList nodes)
    {
        foreach(XmlNode node in nodes)
        {
            int id = node.AttributeAsInt("ID");
            string name = node.AttributeAsString("Name");
            string klasse = node.AttributeAsString("Klasse");
            int level = node.AttributeAsInt("RequiredLevel");
            int cost = node.AttributeAsInt("Cost");
            string effect = node.AttributeAsString("Effect");

            Skill skill = new Skill(
                id, name, klasse, level, cost, effect  
            );
            _skills.Add(skill);
        }
    }

    public static Skill SkillByID(int id)
    {
        Skill? skill = _skills.FirstOrDefault(x => x.ID = id);
        if(skill == null)
        {
            throw new ArgumentException($"SkillID '{id}' does not exist");
        }
        return skill;
    }
}

