using System.Collections.ObjectModel;
using System.ComponentModel;
using Newtonsoft.Json;

namespace Engine.Models;

public abstract class LivingEntity : INotifyPropertyChanged
{
    private GameItem? _currentWeapon;
    private GameItem? _currentConsumable;
    private Skill? _currentSkill;

    public event PropertyChangedEventHandler? PropertyChanged;

    public ObservableCollection<PlayerAttribute> Attributes {get;} =
        new ObservableCollection<PlayerAttribute>();

    public string Name {get;}
    public int CurrentHitPoints {get; private set;}
    public int MaximumHitPoints {get; protected set;}
    public int Gold {get; private set;}
    public int Level {get; protected set;}
    public Inventory Inventory {get; private set;}
    public ObservableCollection<Skill> Skills = new ObservableCollection<Skill>();

    public GameItem? CurrentWeapon
    {
        get{return _currentWeapon;}
        set
        {
            if(_currentWeapon?.Action != null)
            {
                _currentWeapon.Action.OnActionPerformed -= RaiseActionPerformedEvent;
            }
            _currentWeapon = value;
            if(_currentWeapon?.Action != null)
            {
                _currentWeapon.Action.OnActionPerformed += RaiseActionPerformedEvent;
            }
        }
    }

    public Skill? CurrentSkill
    {
        get{return _currentSkill;}
        set
        {
            if(_currentSkill?.Action != null)
            {
                _currentSkill.Action.OnActionPerformed -= RaiseActionPerformedEvent;
            }
            _currentSkill = value;
            if(_currentSkill?.Action != null)
            {
                _currentSkill.Action.OnActionPerformed += RaiseActionPerformedEvent;
            }       
        }
    }

    public GameItem? CurrentConsumable
    {
        get{return _currentConsumable;}
        set
        {
            if(_currentConsumable?.Action != null)
            {
                _currentConsumable.Action.OnActionPerformed -= RaiseActionPerformedEvent;
            }
            _currentConsumable = value;
            if(_currentConsumable?.Action != null)
            {
                _currentConsumable.Action.OnActionPerformed += RaiseActionPerformedEvent;
            }
        }
    }
    [JsonIgnore]
    public bool IsAlive => CurrentHitPoints > 0;
    [JsonIgnore]
    public bool IsDead => !IsAlive;
    public event EventHandler<string>? OnActionPerformed;
    public event EventHandler? OnKilled;

    protected LivingEntity(string name, int maximumHitPoints, int currentHitPoints,
                            IEnumerable<PlayerAttribute> attributes, int gold, int level = 1)
    {
        Name = name;
        MaximumHitPoints = maximumHitPoints;
        CurrentHitPoints = currentHitPoints;
        Gold = gold;
        Level = level;
        foreach(PlayerAttribute attribute in attributes){
            Attributes.Add(attribute);
        }

        Inventory = new Inventory();
    }

    public void UseCurrentWeaponOn(LivingEntity target)
    {
        if(CurrentWeapon == null)
        {
            return;
        }
        CurrentWeapon.PerformAction(this, target);
    }

    public void UseCurrentSpellOn(LivingEntity target)
    {
        if(CurrentSkill == null)
        {
            return;
        }
        CurrentSkill.PerformAction(this, target);
    }

    public void UseCurrentConsumable()
    {
        GameItem? consumable = CurrentConsumable;
        if(consumable == null)
        {
            return;
        }
        consumable.PerformAction(this, this);
        RemoveItemFromInventory(consumable);
    }

    public void TakeDamage(int value)
    {
        CurrentHitPoints -= value;
        if (IsDead)
        {
            CurrentHitPoints = 0;
            RaiseOnKilledEvent();
        }
    }

    public void Heal(int value)
    {
        CurrentHitPoints += value;
        if(CurrentHitPoints > MaximumHitPoints)
        {
            CurrentHitPoints = MaximumHitPoints;
        }
    }

    public void CompleteHeal()
    {
        CurrentHitPoints = MaximumHitPoints;
    }

    public void ReceiveGold(int value)
    {
        Gold += value;
    }

    public void SpendGold(int value)
    {
        if(value > Gold)
        {
            throw new ArgumentOutOfRangeException($"{Name} only has {Gold} gold");
        }
        Gold -= value;
    }

    public void AddItemToInventory(GameItem item)
    {   
        Inventory = Inventory.AddItem(item);
    }

    public void RemoveItemFromInventory(GameItem item)
    {
        ReplaceInventoryAfterRemoval(Inventory.RemoveItem(item));
    }

    public void RemoveItemsFromInventory(List<ItemQuantity> itemQuantities)
    {
        ReplaceInventoryAfterRemoval(Inventory.RemoveItems(itemQuantities));
    }
    public void LearnSkill(Skill skill)
    {
        if(!Skills.Any(s => s.ID == skill.ID))
        {
            Skills.Add(skill);
        }
    }
    // Unequip anything that just left the inventory. Only items that were in the old
    // inventory count: a monster's weapon is never in its inventory and must stay equipped.
    private void ReplaceInventoryAfterRemoval(Inventory newInventory)
    {
        Inventory oldInventory = Inventory;
        Inventory = newInventory;

        if(WasRemoved(CurrentWeapon))
        {
            CurrentWeapon = null;
        }
        if(WasRemoved(CurrentConsumable))
        {
            CurrentConsumable = null;
        }

        bool WasRemoved(GameItem? item) =>
            item != null && oldInventory.Items.Contains(item) && !newInventory.Items.Contains(item);
    }
    private void RaiseOnKilledEvent()
    {
        OnKilled?.Invoke(this, new System.EventArgs());
    }
    private void RaiseActionPerformedEvent(object? sender,string result)
    {
        OnActionPerformed?.Invoke(this, result);
    }
}

