13	    private const string LEGACY_PLAYER_KEY = "Player";
14	    public static void Save(GameState GameState, string fileName)
15	    {
16	        File.WriteAllText(fileName, JsonConvert.SerializeObject(GameState, Formatting.Indented));
17	    }
18	
19	    public static GameState LoadLastSaveOrCreateNew(string fileName)
20	    {
21	        if (!File.Exists(fileName))
22	        {
23	            throw new FileNotFoundException($"Filename: {fileName}");
24	        }
25	        try
26	        {
27	            JObject data = JObject.Parse(File.ReadAllText(fileName));
28	
29	            Party party = CreateParty(data);
30	            int x = (int)data[nameof(GameState.XCoordinate)];
31	            int y = (int)data[nameof(GameState.YCoordinate)];
32	
33	            return new GameState(party, x, y);
34	        }
35	        catch (System.Exception)
36	        {
37	            throw new FormatException($"Error reading: {fileName}");
38	        }
39	    }
40	    private static Party CreateParty(JObject data)
41	    {
